"""Small server-side secrets generated by the app itself (not user config), e.g. the token
of the calendar subscription URL."""

from sqlalchemy import String
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base, TimestampMixin


class AppSecret(TimestampMixin, Base):
    __tablename__ = "app_secrets"

    name: Mapped[str] = mapped_column(String(50), primary_key=True)  # "calendar_token"
    value: Mapped[str] = mapped_column(String(200))
